<?php /** 赛事业务视图；负责人：王乐之（2411302）；AI辅助开发。 */ use yii\helpers\Html;$this->title=$player->name;$goals=0;$cards=0;foreach($player->events as $e){if(in_array($e->type,['goal','penalty_goal'],true))$goals++;if(in_array($e->type,['red_card','yellow_card'],true))$cards++;}?><h1><?= Html::encode($player->name) ?></h1><p>国家队：<?= Html::a(Html::encode($player->team->name),['team/view','id'=>$player->team->id]) ?> · 位置：<?= Html::encode($player->position) ?></p><div class="grid"><div class="card"><h2><?= $goals ?></h2>正式进球</div><div class="card"><h2><?= $cards ?></h2>红黄牌</div></div><h2>赛事事件</h2><table><?php foreach($player->events as $e):?><tr><td><?= Html::a('比赛 #'.$e->match->match_number,['match/view','id'=>$e->match_id]) ?></td><td><?= Html::encode($e->type) ?></td><td><?= $e->minute ?>′</td></tr><?php endforeach ?></table>